:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --accent-hover: #1a4a7a;
  --lock-bg: rgba(0, 0, 0, 0.35);
  --lock-active: #e94560;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 28px 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 1rem;
  color: #9aa5b1;
  margin-bottom: 24px;
}

.palette {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.04);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.color-preview {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  flex-shrink: 0;
  border: 2px solid rgba(255, 255, 255, 0.15);
}

.hex-code {
  font-family: 'SF Mono', 'Consolas', 'Monaco', monospace;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 1px;
  flex: 1;
  text-align: left;
  user-select: all;
}

.lock-btn {
  width: 44px;
  height: 44px;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  background: var(--lock-bg);
  color: var(--text);
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
  flex-shrink: 0;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.4);
}

.lock-btn:focus-visible {
  outline: 3px solid #4fc3f7;
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.92);
}

.lock-btn[aria-pressed="true"] {
  background: var(--lock-active);
  border-color: var(--lock-active);
  color: #fff;
}

.generate-btn {
  width: 100%;
  padding: 16px 24px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: var(--font);
  color: #fff;
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  letter-spacing: 1px;
  transition: background 0.15s ease, transform 0.1s ease;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 3px solid #4fc3f7;
  outline-offset: 2px;
}

.generate-btn:active {
  transform: scale(0.98);
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px;
  }

  h1 {
    font-size: 1.4rem;
  }

  .color-preview {
    width: 40px;
    height: 40px;
  }

  .hex-code {
    font-size: 1rem;
  }

  .swatch {
    padding: 10px 12px;
    gap: 10px;
  }

  .lock-btn {
    width: 40px;
    height: 40px;
    font-size: 1rem;
  }
}

const paletteEl = document.getElementById('palette');
const generateBtn = document.getElementById('generate');

let locked = [false, false, false, false, false];
let currentColors = [];

function hslToHex(h, s, l) {
  const a = s * Math.min(l, 1 - l);
  const f = (n) => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
}

function generateHarmoniousPalette() {
  const baseHue = Math.random() * 360;
  const scheme = Math.floor(Math.random() * 3);
  const hues = [];

  if (scheme === 0) {
    // Analogous
    for (let i = 0; i < 5; i++) {
      hues.push((baseHue + i * 30 - 60 + 360) % 360);
    }
  } else if (scheme === 1) {
    // Complementary split
    const comp = (baseHue + 180) % 360;
    hues.push(baseHue, (baseHue + 30) % 360, comp, (comp + 30) % 360, (baseHue + 15) % 360);
  } else {
    // Triadic
    const t1 = (baseHue + 120) % 360;
    const t2 = (baseHue + 240) % 360;
    hues.push(baseHue, t1, t2, (baseHue + 60) % 360, (t1 + 60) % 360);
  }

  return hues.map((h, i) => {
    const s = 0.5 + Math.random() * 0.3;
    const l = 0.35 + (i / 4) * 0.3 + Math.random() * 0.1;
    return hslToHex(h, s, Math.min(l, 0.85));
  });
}

function render() {
  paletteEl.innerHTML = '';
  currentColors.forEach((color, i) => {
    const swatch = document.createElement('div');
    swatch.className = 'swatch';

    const preview = document.createElement('div');
    preview.className = 'color-preview';
    preview.style.backgroundColor = color;

    const hex = document.createElement('span');
    hex.className = 'hex-code';
    hex.textContent = color;

    const lockBtn = document.createElement('button');
    lockBtn.type = 'button';
    lockBtn.className = 'lock-btn';
    lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
    lockBtn.setAttribute('aria-label', `${locked[i] ? 'Unlock' : 'Lock'} color ${color}`);
    lockBtn.textContent = locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13';

    lockBtn.addEventListener('click', () => {
      locked[i] = !locked[i];
      render();
    });

    swatch.appendChild(preview);
    swatch.appendChild(hex);
    swatch.appendChild(lockBtn);
    paletteEl.appendChild(swatch);
  });
}

function generate() {
  const newColors = generateHarmoniousPalette();
  currentColors = currentColors.length === 5
    ? currentColors.map((c, i) => (locked[i] ? c : newColors[i]))
    : newColors;
  render();
}

generateBtn.addEventListener('click', generate);

// Initial palette
generate();
